package com.colovision.service;
import com.colovision.model.*; import java.io.*; import java.nio.file.*; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.font.PDType1Font; import org.apache.pdfbox.pdmodel.font.Standard14Fonts; import org.apache.pdfbox.pdmodel.PDPageContentStream; import org.springframework.stereotype.Service;
@Service public class ReportService { public void write(Path path,Patient p,Prediction x)throws IOException{Files.createDirectories(path.getParent());try(PDDocument d=new PDDocument()){PDPage page=new PDPage();d.addPage(page);try(PDPageContentStream c=new PDPageContentStream(d,page)){c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),12);float y=780;for(String line:new String[]{"COLORECTAL CANCER DETECTION","DEEP LEARNING ANALYSIS REPORT","","Patient ID: "+p.patientId,"Patient: "+p.name,"Age / Gender: "+p.age+" / "+p.gender,"Analysis: "+x.createdAt,"","Predicted Tissue Class: "+x.predictedClass,String.format("Confidence: %.2f%%",x.confidence*100),"","Research and decision-support use only. Not a definitive medical diagnosis."}){c.beginText();c.newLineAtOffset(50,y);c.showText(line);c.endText();y-=25;}}d.save(path.toFile());}} }
